package cl.bolsillo.app;
import android.animation.*;import android.content.Context;import android.view.*;import android.widget.*;import java.util.*;
/** Measured anchors and interrupted gestures always settle to a complete card. */
final class SnapCarousel extends HorizontalScrollView {
 ValueAnimator spring;int startPage,peek;java.util.function.IntConsumer changed;boolean fullWidth,flung,restoreAnchor;float downX,downY;
 SnapCarousel(Context c){super(c);setHorizontalScrollBarEnabled(false);setOverScrollMode(OVER_SCROLL_NEVER);setPadding(0,Glass.dp(c,4),0,Glass.dp(c,8));setClipToPadding(false);setClipChildren(false);}
 /** Space for card elevation belongs to the viewport, not each horizontal anchor. */
 @Override public void onViewAdded(View child){super.onViewAdded(child);if(child instanceof ViewGroup){ViewGroup strip=(ViewGroup)child;strip.setClipToPadding(false);strip.setClipChildren(false);}}
 /** The viewport must determine card widths before the strip is measured, including its first frame. */
 private boolean fitCards(int viewport){if(!fullWidth||getChildCount()==0||viewport<=0)return false;ViewGroup strip=(ViewGroup)getChildAt(0);int target=Math.max(1,viewport-getPaddingLeft()-getPaddingRight()-Glass.dp(getContext(),peek));boolean changedWidth=false;for(int i=0;i<strip.getChildCount();i++){View card=strip.getChildAt(i);ViewGroup.LayoutParams params=card.getLayoutParams();if(params.width!=target){params.width=target;card.setLayoutParams(params);changedWidth=true;}}if(changedWidth){if(spring!=null){spring.cancel();spring=null;}restoreAnchor=true;}return changedWidth;}
 @Override protected void onMeasure(int widthSpec,int heightSpec){if(MeasureSpec.getMode(widthSpec)!=MeasureSpec.UNSPECIFIED)fitCards(MeasureSpec.getSize(widthSpec));super.onMeasure(widthSpec,heightSpec);if(fitCards(getMeasuredWidth()))super.onMeasure(widthSpec,heightSpec);}
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);if(fullWidth&&getChildCount()>0)restoreAnchor=true;}
 List<Integer> anchors(){List<Integer> result=new ArrayList<>();if(getChildCount()==0)return result;ViewGroup strip=(ViewGroup)getChildAt(0);int max=Math.max(0,strip.getWidth()-getWidth());for(int i=0;i<strip.getChildCount();i++){int x=Math.min(max,strip.getChildAt(i).getLeft());if(result.isEmpty()||result.get(result.size()-1)!=x)result.add(x);}return result;}
 int page(){List<Integer> a=anchors();int best=0;for(int i=1;i<a.size();i++)if(Math.abs(getScrollX()-a.get(i))<Math.abs(getScrollX()-a.get(best)))best=i;return best;}
 void go(int page){List<Integer> a=anchors();if(a.isEmpty())return;int selected=Math.max(0,Math.min(a.size()-1,page));startPage=selected;int target=a.get(selected);if(spring!=null){spring.cancel();spring=null;}if(target==getScrollX()||!ValueAnimator.areAnimatorsEnabled())scrollTo(target,0);else{spring=ValueAnimator.ofInt(getScrollX(),target);spring.setDuration(230);spring.setInterpolator(PageMotion.EASE);spring.addUpdateListener(v->scrollTo((Integer)v.getAnimatedValue(),0));spring.start();}if(changed!=null)changed.accept(selected);}
 @Override protected void onLayout(boolean changedLayout,int l,int t,int r,int b){super.onLayout(changedLayout,l,t,r,b);if(restoreAnchor){restoreAnchor=false;List<Integer> a=anchors();if(!a.isEmpty()){startPage=Math.max(0,Math.min(startPage,a.size()-1));scrollTo(a.get(startPage),0);if(changed!=null)changed.accept(startPage);}}}
 @Override public void fling(int velocityX){flung=true;go(Math.abs(velocityX)>ViewConfiguration.get(getContext()).getScaledMinimumFlingVelocity()?startPage+(velocityX>0?1:-1):page());}
 @Override public boolean dispatchTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){if(spring!=null)spring.cancel();startPage=page();flung=false;downX=e.getX();downY=e.getY();}boolean result=super.dispatchTouchEvent(e);if((e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)&&!flung&&isAttachedToWindow())go(page());return result;}
 @Override public boolean onInterceptTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&Math.abs(e.getX()-downX)>Glass.dp(getContext(),10)&&Math.abs(e.getX()-downX)>Math.abs(e.getY()-downY)*1.2f)getParent().requestDisallowInterceptTouchEvent(true);return super.onInterceptTouchEvent(e);}
 @Override protected void onDetachedFromWindow(){if(spring!=null)spring.cancel();super.onDetachedFromWindow();}
}
